value.fa:
// گام مشخص (نزولی)
برای (عدد i = 10; i > 0; گام 2) {
    چاپ(i);
}

// گام هوشمند (خالی = تشخیص خودکار جهت و گام 1)
برای (عدد i = 0; i < 4;) {
    چاپ("  i = " + i);
}

// گام مشخص (صعودی)
برای (عدد i = 34; i > 3; گام 3) {
    چاپ("  مقدار i = " + i);
}

value.en:
// Explicit step (descending)
for (int i = 10; i > 0; step 2) {
    print(i);
}

// Smart step (empty = auto-detect direction and step 1)
for (int i = 0; i < 4;) {
    print("  i = " + i);
}

// Explicit step (ascending logic handled by compiler)
for (int i = 34; i > 3; step 3) {
    print("  value i = " + i);
}

value.ja:
// 明示的なステップ（降順）
のために (整数 i = 10; i > 0; ステップ 2) {
    表示(i);
}

// スマートステップ（空 = 方向とステップ1を自動検出）
のために (整数 i = 0; i < 4;) {
    表示("  i = " + i);
}

// 明示的なステップ
のために (整数 i = 34; i > 3; ステップ 3) {
    表示("  値 i = " + i);
}

value.ru:
// Явный шаг (по убыванию)
для (цел i = 10; i > 0; шаг 2) {
    печать(i);
}

// Умный шаг (пусто = автоопределение направления и шаг 1)
для (цел i = 0; i < 4;) {
    печать("  i = " + i);
}

// Явный шаг
для (цел i = 34; i > 3; шаг 3) {
    печать("  значение i = " + i);
}
